<script setup>


import {computed, ref, watch, onBeforeUnmount} from 'vue'
import {quoteKey, redisContentCommand, appendKeys, appendRedisValues, redisValues, prettyValue} from './browserModel.js'
const props=defineProps({state:Object,target:Object,execute:Function,disabled:Boolean,approval:Boolean,canChange:Boolean,consoleMode:Boolean,navigationOpen:{type:Boolean,default:true}})
const emit=defineEmits(['change','browse','close-navigation']),s=props.state,pending=ref(false),message=ref(''),navigationMessage=ref(''),exactKey=ref('')
if(!s.keys)Object.assign(s,{keys:[],pattern:'',cursor:'0',scanned:false,capped:false,key:'',type:'',ttl:null,values:[],value:null,contentLoaded:false,contentCursor:'0',contentDone:false,contentCapped:false,offset:0,truncated:false})
const disabled=computed(()=>props.disabled||pending.value||!props.target)
const ttlText=computed(()=>s.ttl===-2?'Key 已不存在':s.ttl===-1?'不过期':s.ttl===null?'':s.ttl+' 秒')
const viewRows=computed(()=>redisValues(s.type,s.values))
let lastRequest=0,disposed=false
onBeforeUnmount(()=>{disposed=true})
async function perform(commands,navigation=false){const feedback=navigation?navigationMessage:message;feedback.value='';pending.value=true;try{const delay=Math.max(0,250-(Date.now()-lastRequest));if(delay)await new Promise(resolve=>setTimeout(resolve,delay));if(disposed)return null;lastRequest=Date.now();return await props.execute({commands})}catch(e){feedback.value=e.message;return null}finally{pending.value=false}}
async function search(next=false){if(disabled.value)return;if(next&&(s.cursor==='0'||s.capped))return;const pattern=next?s.appliedPattern:(s.pattern||props.target.key_prefix+'*');if(!next){s.keys=[];s.cursor='0';s.scanned=false;s.capped=false;s.appliedPattern=pattern}
 const result=await perform('SCAN '+s.cursor+' MATCH '+quoteKey(pattern)+' COUNT 50',true);if(result)accept(result)
}
function resetContent(){s.values=[];s.value=null;s.contentLoaded=false;s.contentCursor='0';s.contentDone=false;s.contentCapped=false;s.offset=0;s.truncated=false}
function accept(result){for(const row of result.rows||[]){const a=row.argv||[],value=row.result;
 if(a[0]==='SCAN'&&Array.isArray(value)&&Array.isArray(value[1])){const page=appendKeys(s.keys,value[1]);s.keys=page.keys;s.capped=page.capped;s.cursor=String(value[0]);s.scanned=true;s.appliedPattern=a[3];s.pattern=a[3]}
 else if(a[0]==='TYPE'){if(s.key!==a[1])resetContent();s.key=a[1];s.type=String(value);if(s.type==='none')resetContent()}
 else if(a[0]==='TTL'){s.key=a[1];s.ttl=Number(value);if(s.ttl===-2){s.type='none';resetContent()}}
 else if(a[0]==='GET'){s.key=a[1];s.type=value===null?'none':'string';if(value===null)s.ttl=-2;s.value=value;s.contentLoaded=true;s.contentDone=true;s.truncated=!!row.truncated}
 else if(['HSCAN','SSCAN','ZSCAN'].includes(a[0])&&Array.isArray(value)&&Array.isArray(value[1])){s.key=a[1];s.type={HSCAN:'hash',SSCAN:'set',ZSCAN:'zset'}[a[0]];if(String(a[2])==='0')resetContent();const batch=appendRedisValues(s.type,s.values,value[1]);s.values=batch.values;s.contentCapped=batch.capped;s.contentCursor=String(value[0]);s.contentDone=s.contentCursor==='0';s.contentLoaded=true}
 else if(a[0]==='LRANGE'&&Array.isArray(value)){s.key=a[1];s.type='list';if(Number(a[2])===0)resetContent();const batch=appendRedisValues('list',s.values,value);s.values=batch.values;s.offset=Number(a[3])+1;s.contentDone=value.length<50;s.contentCapped=batch.capped;s.contentLoaded=true}
 }}
async function inspect(key){if(disabled.value||!key)return;emit('browse');s.key=key;s.type='';s.ttl=null;resetContent();const result=await perform('TYPE '+quoteKey(key)+'\nTTL '+quoteKey(key));if(!result)return;accept(result);if(!props.approval&&s.type!=='none')await content(false)}
async function content(next=false){if(next&&(s.contentDone||s.contentCapped))return;const command=redisContentCommand(s.key,s.type,next?s.contentCursor:'0',next?s.offset:0);if(!command){message.value='此类型暂不支持内容预览，可在命令控制台查询支持的只读命令';return}const result=await perform(command);if(result)accept(result)}
watch(()=>s.restore,restore=>{if(restore){delete s.restore;accept(restore.result)}},{immediate:true})



import {Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'
</script>
<template><section aria-label="Redis Key 浏览" class="resource-browser redis-key-browser" :class="{'no-target':!target}"><aside v-show="navigationOpen&&!!target"><div class="browser-head"><b>Key 浏览</b><small>{{target?'DB '+target.db:'请选择连接'}}</small></div><form v-if="target" @submit.prevent="search(false)" class="browser-search"><Input v-model="s.pattern" :placeholder="(target?.key_prefix||'前缀:')+'*'" :disabled="disabled" v-bind="{&quot;aria-label&quot;:&quot;Key 搜索模式&quot;}"/><Button variant="outline" size="default" type="submit" :disabled="(disabled)">{{approval?'申请搜索':'搜索'}}</Button></form><p v-if="navigationMessage" role="alert" class="browser-error">{{navigationMessage}}</p><small>范围：{{target?.key_prefix||'未选择'}} · 每次 SCAN COUNT 50</small><p v-if="s.scanned" class="browser-hint">已加载 {{s.keys.length}} 个 Key · {{s.cursor==='0'?'本轮扫描结束':'还可继续扫描'}}</p><div class="object-list"><Button v-for="key in s.keys" :key="key" :class="{selected:s.key===key}" @click="inspect(key)" variant="outline" size="default" type="button" :disabled="(disabled)">{{key}}</Button></div><p v-if="!s.scanned" class="empty">输入模式后点击搜索。页面不会自动扫描。</p><p v-else-if="!s.keys.length" class="empty">本批没有匹配 Key，游标未结束时可继续扫描。</p><Button v-if="s.scanned" @click="search(true)" class="load-more" variant="outline" size="default" type="button" :disabled="(disabled||s.cursor==='0'||s.capped)">{{pending?'读取中…':approval?'申请加载更多':'加载更多'}}</Button><p v-if="s.capped" class="browser-hint">已达到浏览上限（1000 个或 2 MiB），结果可能不完整。请缩小搜索范围。</p></aside><Button v-if="navigationOpen&&!!target" aria-label="收起 Key 导航" @click="emit('close-navigation')" class="navigator-backdrop" variant="outline" size="default" type="button"></Button><div v-show="consoleMode" class="browser-detail console-detail"><slot name="console"/></div><div v-show="!consoleMode" class="browser-detail redis-detail"><form v-if="target" @submit.prevent="inspect(exactKey)" class="browser-search"><Input v-model="exactKey" placeholder="输入准确 Key，可直接查看" :disabled="disabled" v-bind="{&quot;aria-label&quot;:&quot;直接查看 Key&quot;}"/><Button variant="outline" size="default" type="submit" :disabled="(disabled||!exactKey)">{{approval?'申请查看':'查看 Key'}}</Button></form><p v-if="message" role="alert" class="browser-error">{{message}}</p><Empty v-if="!s.key" class="browser-empty"><EmptyHeader><EmptyDescription>{{target?'选择 Key 后读取类型、TTL 和内容；列表不会批量读取详情。':'先在上方选择连接，或选择应用和逻辑资源。'}}</EmptyDescription></EmptyHeader></Empty><template v-else><div class="browser-head key-title"><b>{{s.key}}</b><span class="type-badge">{{s.type||(pending?'读取中':message?'读取失败':approval?'待审批':'尚未读取')}}</span><small v-if="ttlText">TTL：{{ttlText}}</small></div><div class="browser-actions"><Button @click="inspect(s.key)" variant="outline" size="default" type="button" :disabled="(disabled)">{{approval?'申请刷新详情':'刷新详情'}}</Button><Button v-if="s.type&&s.type!=='none'" @click="content(false)" variant="outline" size="default" type="button" :disabled="(disabled)">{{approval?'申请读取内容':'重新读取内容'}}</Button><Button @click="emit('change',{key:s.key,command:'EXPIRE'})" variant="outline" size="default" type="button" :disabled="(disabled||!canChange||!s.type||s.type==='none')">新建过期草稿</Button><Button @click="emit('change',{key:s.key,command:'UNLINK'})" variant="outline" size="default" type="button" :disabled="(disabled||!canChange||!s.type||s.type==='none')">新建清理草稿</Button></div><p v-if="!canChange" class="browser-hint">直接连接支持只读浏览；提交变更前请关联应用资源。</p><p v-if="s.type==='none'" class="empty">Key 已过期或被删除，请重新搜索。</p><template v-else-if="s.contentLoaded"><p v-if="s.truncated" class="browser-hint">仅预览前 64 KiB，内容已截断。</p><pre v-if="s.type==='string'" class="string-preview">{{prettyValue(s.value)}}</pre><template v-else><div class="collection-scroll"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:780}).y?({x:780}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:780}).x||({x:780}).minWidth||780)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(260)+'px'}">{{s.type==='hash'?'字段':s.type==='zset'?'成员':'序号'}}</TableHead><TableHead :style="{width:(520)+'px'}">{{s.type==='zset'?'分值':'内容'}}</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((viewRows)||[]).map((row,rowIndex)=>({...row,__rowKey:row.name}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{row.name}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:row,rowIndex:rowIndex} in [{record,rowIndex}]"><div><pre class="collection-value">{{prettyValue(row.value)}}</pre></div></template></div></TableCell></TableRow></template><TableRow v-if="!(((viewRows)||[]).map((row,rowIndex)=>({...row,__rowKey:row.name}))||[]).length"><TableCell :colspan="2"><Empty><EmptyHeader><EmptyDescription>本批没有成员，未结束时可继续读取。</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div><div class="browser-pagination"><span>已展示 {{viewRows.length}} 项 · {{s.contentDone?'本轮读取结束':'分批读取中'}}</span><Button @click="content(true)" variant="outline" size="default" type="button" :disabled="(disabled||s.contentDone||s.contentCapped)">{{approval?'申请更多内容':'加载更多内容'}}</Button></div><p v-if="s.contentCapped" class="browser-hint">已达到内容展示上限（1000 项或 2 MiB），停止继续读取。</p></template></template><p v-else-if="s.type&&s.type!=='none'" class="empty">{{pending?'正在读取内容…':message?'内容未读取，请重试。':approval?'点击“申请读取内容”继续，仍遵循查询审批。':'尚未读取内容，可点击“重新读取内容”。'}}</p></template></div></section></template>
<style src="./browser.css"></style>

<style scoped>.browser-empty{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;min-height:180px}</style>
